events=[]
class Keyword(str):
    __hash__ = str.__hash__
    def __eq__(self, other):
        raise AssertionError('keyword equality override')
    def __str__(self):
        raise AssertionError('keyword str override')
    def __iter__(self):
        raise AssertionError('keyword iter override')
    def __len__(self):
        raise AssertionError('keyword len override')
def key(value):
    events.append(('key', value))
    return -value
class Reverse:
    def __bool__(self):
        events.append('reverse')
        return True
class Source:
    def __iter__(self):
        events.append('iter')
        return iter([3,1,2])
    def __len__(self):
        events.append('len')
        return 3
items=[3,1,2]

try:
    value=min([3,1,2], **{Keyword('key'):key})
    result=('ok',type(value).__name__,repr(value),value is items)
except BaseException as error:
    result=('exception',type(error).__name__,str(error),error.args)
result=(result,events,items)

